const A='https://filestore.aqa.org.uk/resources/english/AQA-8702-TG-POEMS.PDF';
const I='https://www.concordtheatricals.com/p/12689/an-inspector-calls';
const R='https://rpo.library.utoronto.ca/content/birthday';
export const birthday=`A Birthday — Christina Rossetti

My heart is like a singing bird
    Whose nest is in a water'd shoot;
My heart is like an apple-tree
    Whose boughs are bent with thickset fruit;
My heart is like a rainbow shell
    That paddles in a halcyon sea;
My heart is gladder than all these
    Because my love is come to me.

Raise me a dais of silk and down;
    Hang it with vair and purple dyes;
Carve it in doves and pomegranates,
    And peacocks with a hundred eyes;
Work it in gold and silver grapes,
    In leaves and silver fleurs-de-lys;
Because the birthday of my life
    Is come, my love is come to me.`;
export const london=`London — William Blake

I wander through each chartered street,
Near where the chartered Thames does flow,
And mark in every face I meet
Marks of weakness, marks of woe.

In every cry of every man,
In every infant’s cry of fear,
In every voice, in every ban,
The mind-forged manacles I hear:

How the chimney-sweeper’s cry
Every black’ning church appalls,
And the hapless soldier’s sigh
Runs in blood down palace walls.

But most through midnight streets I hear
How the youthful harlot’s curse
Blasts the new-born infant’s tear,
And blights with plagues the marriage hearse.`;
const make=d=>{
 const topic=d.topic||'power-conflict',id=`lit.${topic}.${d.key}`,play=topic==='inspector',full=topic==='unseen',ref=play?'3.2.1':full?'3.2.3':'3.2.2';
 const qs=(stage,rows)=>rows.map(([prompt,correct,a,b,why,concept],i)=>{const answer=(i+d.key.length)%3,options=[a,b];options.splice(answer,0,correct);return{id:`${id}.${stage}.${i+1}`,prompt,options,answer,why,concept:`${id}.${concept}`};});
 const sources=d.sources||[play?I:full?R:A];
 return{id,topicId:`english-literature.${play?'inspector-calls':topic}`,title:d.title,scope:d.scope,minutes:d.minutes||30,refs:[ref,'3.3'],author:full?'Christina Rossetti':play?'J.B. Priestley':'Selected poets',rights:full?'public_domain':'protected_summary_only',textType:play?'play':'poem',textTitle:full?'A Birthday':play?'An Inspector Calls':'Power and Conflict anthology',readingURL:play?null:full?R:A,checked:'29 October 2026',sources,contextReading:sources.map(url=>({url,label:url===I?'An Inspector Calls · publisher and authorised editions':url===R?'A Birthday · 1890 text source':'AQA Power and Conflict · assigned anthology'})),sourceNote:full?'Complete underlying public-domain poem A Birthday by Christina Rossetti, 16 lines in two stanzas. Wording follows the 1890 Poems text reproduced by Representative Poetry Online; original commentary and glosses. Unfamiliar-reading practice, not a set poem or official exam question. Prior familiarity means a later attempt is revision rather than unseen reading.':d.sourceNote||`Original teaching commentary on ${play?'the protected play':'the assigned poems'}, not a quotation or reproduced passage. Read ${play?'an authorised full copy':'the complete assigned texts'} for exact evidence. Speakers are not automatically authors; interpretations need support and can differ.`,explorerNote:full?'Complete public-domain poem; original commentary and vocabulary glosses. Source and edition in Sources & notes.':undefined,cards:d.cards,views:[{kind:'language',label:full?'Read the poem':play?'Dramatic lenses':'Comparison lenses',title:full?'A Birthday':d.scope,content:full?birthday:d.summary,words:d.details,originalSummary:!full,textType:play?'play':'poem',readingRegion:true,...(full?{fullText:true}:{})},{kind:'people',label:'Compare perspectives',title:'Test the positions',rows:d.people},{kind:'timeline',label:'Develop the argument',title:'Trace the reasoning',events:d.movement}],tasks:[[d.challenge[0],d.challenge.slice(1,4),0,d.challenge[4],d.challenge[5]]],practice:qs('practice',d.practice),check:qs('check',d.check),writing:d.writing,rubric:d.rubric,...(d.extra||{})};
};
export const batch12=[
make({topic:'inspector',key:'workshop-09',title:'Eva absence and represented voices',scope:'Whole play · who gets to tell a life?',summary:'Teaching lens: Eva is not present as a speaking character in the inquiry. Her experience reaches the audience through accounts, questions and a photograph. Evaluate the voices representing her rather than mistaking any one account for unrestricted access to her thoughts.',
cards:[['Make absence an interpretive question','Read a particular account of Eva in your authorised copy. Ask who selects the information, what relationship that speaker had with her and what the audience cannot hear directly. Absence from the stage does not make her insignificant: it can make the power to describe another person a central problem.'],['Separate representation from complete knowledge','A photograph and testimony can focus attention while leaving questions about identity, motive and sequence unsettled. Do not assume a speaker’s account gives direct access to Eva’s full inner life. Explain what the representation allows an audience to know and where your judgment needs qualification.'],['Keep the person beyond the family’s story','The inquiry can expose harm while still presenting it through socially powerful people’s speech. A strong argument considers that tension rather than reducing Eva to a device that improves the family. Use a specific narrative omission or change of description to ask whose experience is made visible and whose remains mediated.']],details:[['Account','Identify who selects the details and why that matters.'],['Photograph','Consider attention and recognition without assuming total certainty.'],['Absent voice','Absence creates a question about representation, not insignificance.']],people:[['Person described','Has experiences not fully accessible through another speaker.'],['Family narrators','Select accounts of their own involvement.'],['Audience','Judges both conduct and the limits of the retelling.']],movement:[['Locate','Choose one particular account.'],['Attribute','Name the speaker’s position and access.'],['Question','Identify what remains unheard or uncertain.'],['Argue','Explain why mediated representation matters.']],challenge:['Which reading respects the limits of representation?','Eva’s absence makes the power and limits of others’ accounts important.','A photograph reveals every private thought with certainty.','No onstage speech means Eva has no significance.','Absence can shape a drama’s ethical attention without supplying omniscience.','Distinguish a represented person from complete access to that person.'],practice:[['What should an account analysis identify first?','Who speaks and what access that person has.','Only how many sentences the account contains.','An assumption the audience hears Eva directly.','Attribution helps establish the evidence’s status.','voice'],['Why does an omission matter?','It can show the limits of what the retelling allows the audience to know.','Every missing detail proves a particular invented motive.','Absence makes all evidence unusable.','A limit requires qualification rather than invention.','methods'],['Which reduction should be resisted?','Eva matters only as a device to improve the family.','The family’s accounts shape audience access.','The photograph has a dramatic function.','An ethical reading attends to the person harmed beyond a plot function.','ethics']],check:[['What is central to Eva’s presentation?','Her experience is mediated through other voices.','The audience hears an unbroken personal soliloquy from her.','Every motive is independently confirmed.','Distinguish representation from direct speech and omniscience.','meaning'],['What can a photograph not establish by itself?','Complete certainty about every private motive and event.','A focus for a character’s recognition.','A source of attention within the inquiry.','Visual evidence also has an appropriate scope.','limits'],['Which question develops voice analysis?','How does this speaker’s position shape the account selected?','Which invented quotation would settle all uncertainty?','Why should all absent people be ignored?','Relate access and selection to the act of telling.','methods'],['What makes the ethical judgment qualified?','Consider harm and the limits of the family’s representation together.','Assume no direct voice means no important experience.','Treat one account as a complete inner biography.','The drama can expose wrongdoing while leaving representation itself open to scrutiny.','argument']],writing:'How does Eva’s absence affect the power of others to represent her? Analyse one particular account and an omission, distinguishing what the audience learns from what remains uncertain.',rubric:['Attribute a specific account and explain the speaker’s access and position.','Analyse selection or omission without inventing an absent person’s thoughts.','Keep the person harmed significant beyond the family’s moral development.']}),
make({topic:'inspector',key:'workshop-10',title:'The Inspector final speech close reading',scope:'Act 3 · individual acts and collective warning',summary:'Teaching lens: the Inspector’s final address expands from the inquiry into a claim about collective responsibility and consequences. Read the exact pronouns, repetitions and warning in the authorised play before deciding how its authority is constructed.',
cards:[['Read the address as an argument','In an authorised copy, trace how the Inspector moves from individual involvement to a wider claim about social obligation. Identify a precise pronoun or repeated structure and explain whom it includes. Naming the speech as important is not yet analysis of how it seeks assent or challenges the listeners.'],['Explain the warning’s persuasive work','A warning projects consequences and can put pressure on the family’s priorities. Analyse its scale and verbal pattern without assuming the speech supplies a verified account of every future event. A forceful ethical statement can be central to the play while remaining a dramatic utterance delivered by a particular figure.'],['Test authority through the surrounding drama','Compare the final address with the family’s responses after the departure. Agreement, evasion and renewed uncertainty provide evidence about its effect. Do not claim that the speaker’s force proves a single identity for the Inspector or that every audience must treat every implication as the author’s literal personal declaration.']],details:[['Collective reference','Identify the actual pronoun and whom it includes.'],['Repetition','Explain how the pattern develops the argument.'],['Warning','Distinguish persuasive projection from a fully verified future.']],people:[['Inspector','Constructs an address extending beyond the immediate inquiry.'],['Family','Responds differently to the responsibility proposed.'],['Audience','Tests authority through both speech and subsequent conduct.']],movement:[['Trace','Follow the movement from particular acts to wider duty.'],['Analyse','Locate a pronoun or repeated pattern.'],['Test','Compare the warning with later responses.'],['Qualify','Separate ethical force from certainty about identity.']],challenge:['Which analysis goes beyond a theme label?','Explain how a specific collective pronoun widens the address’s scope.','Call the speech important and provide no textual detail.','Assume forceful delivery proves one identity beyond dispute.','A method becomes evidence when its work in the argument is explained.','Locate the exact feature and the relation it creates.'],practice:[['What should pronoun analysis establish?','Who is included and how that advances the claim.','A universal rule that every pronoun means equality.','An invented version of the speech.','Meaning depends on reference and argumentative context.','methods'],['How can the later family debate help?','It tests how the address affects different priorities.','It proves everyone responds identically.','It removes the need to read the address.','Effects can be considered through subsequent conduct.','structure'],['Which conclusion exceeds the speech?','Its force alone establishes a single incontrovertible identity.','It offers a claim about collective obligation.','The warning can challenge complacency.','Persuasive authority and identity certainty are different things.','limits']],check:[['What is the address’s change in scale?','It connects particular involvement with wider social responsibility.','It remains only a neutral timetable of the dinner.','It guarantees no listener can disagree.','Trace how an ethical argument develops its scope.','meaning'],['Which method claim needs exact text?','A particular repetition creates emphasis or progression in the argument.','Every long speech always has the same meaning.','The speaker’s name supplies all necessary evidence.','Locate a real pattern before interpreting its function.','evidence'],['What should a warning not be confused with?','A verified account of every future event.','A way to project consequences persuasively.','An occasion for testing the family’s response.','A projection has a dramatic and rhetorical function.','interpretation'],['What supports a qualified judgment about authority?','Read the speech alongside contrasting responses and unresolved questions.','Invent a definitive identity to avoid analysing the address.','Claim every audience has an identical response.','Use the surrounding drama to test rather than simply repeat authority.','argument']],writing:'How does the Inspector’s final address construct collective responsibility? Analyse exact wording from your authorised copy and test its authority through a later family response.',rubric:['Analyse a precise verbal pattern and its role in the argument.','Explain the movement between individual conduct and collective responsibility.','Test authority through surrounding responses without claiming a definitive identity or universal audience.']}),
make({topic:'inspector',key:'workshop-11',title:'1912 setting and later audience context workshop',scope:'Setting and reception · knowledge used critically',summary:'Teaching lens: the 1912 setting gives later audiences a different view of confident forecasts and social security. The play’s first performances were in 1945, followed by its British premiere in 1946; audiences in different places and times need not respond identically.',
cards:[['Keep setting and first performance distinct','The dinner is set in 1912; the play first reached audiences in 1945 and then Britain in 1946. These are different contexts, not interchangeable dates. Use the gap to explain a particular forecast or social assumption in the dialogue, rather than assuming the characters possess later historical knowledge.'],['Make a context fact do analytical work','Choose one confident claim and explain what a later audience can recognise differently. The significance comes from the relation between history and the speech’s performance of authority. A paragraph about unrelated background facts may be accurate yet fail to analyse the play’s chosen arrangement of knowledge.'],['Avoid an invented unanimous audience','Different audiences can know different histories and hold different political views. Qualify an effect and support it through the dramatic detail. The setting can invite scrutiny of self-assurance without automatically dictating one interpretation of every character or proving that every viewer in 1945 or today agrees.']],details:[['1912','The dramatic setting locates the characters’ knowledge.'],['1945 / 1946','First performance and British premiere differ from the setting.'],['Knowledge gap','Context matters when it changes the judgment of a specific claim.']],people:[['1912 character','Acts within the represented historical position.'],['Early audiences','Encounter the play after later historical events.'],['Current reader','Must support and qualify an interpretation rather than invent consensus.']],movement:[['Distinguish','Keep the represented time separate from performance history.'],['Locate','Choose a particular claim in the play.'],['Relate','Explain what later knowledge changes.'],['Qualify','Allow differences in audience knowledge and judgment.']],challenge:['Which context sentence is analytical?','The later knowledge gap can unsettle the authority of this particular forecast.','The characters know all events after 1912 because the play was staged later.','Every audience must share one political judgment.','Context earns its place through a relation to a textual choice.','Link the verified fact with the exact speech being discussed.'],practice:[['Which dates should remain distinct?','The 1912 setting and later first performances.','Every date as if it describes the same event.','A character’s age and an invented film release.','Represented time and reception are different contexts.','context'],['What turns background knowledge into analysis?','Explain how it affects a specific claim’s authority or meaning.','Add facts with no relation to a speech.','Assume history removes the need for evidence.','A relevant relation matters more than the quantity of facts.','methods'],['Which audience statement is defensible?','Viewers with later knowledge may question the confident forecast.','Every viewer everywhere necessarily reacts identically.','No audience can ever use historical knowledge.','Qualify an effect through the knowledge needed for it.','audience']],check:[['What is the represented setting date?','1912, distinct from the later performance history.','1946, because no play can represent an earlier time.','The play has no represented social setting.','Keep separate the time of action and the time of reception.','meaning'],['Which mistake moves knowledge incorrectly?','Giving a 1912 character knowledge solely available through later events.','Distinguishing later audience knowledge from the character’s position.','Reading a forecast within its immediate exchange.','A later performance does not update the character’s represented knowledge.','accuracy'],['What makes a contextual effect qualified?','Name the relevant knowledge and say how it may shape judgment.','Assert a single compulsory reaction for every viewer.','Replace the speech with a list of dates.','Audience claims need a basis and appropriate limits.','interpretation'],['What should a context paragraph retain?','Close attention to the particular textual choice it explains.','Only background facts and no argument about the play.','A claim that one date determines every meaning.','Context should serve evidence-led reasoning.','argument']],writing:'How does the gap between the 1912 setting and later audiences shape a judgment of authority? Analyse one particular claim, keep dates distinct and qualify the audience effect.',rubric:['Distinguish dramatic setting from first performance and reception accurately.','Use a relevant historical fact to explain a specific textual choice.','Qualify audience effects without inventing unanimous knowledge or political agreement.']}),
make({topic:'inspector',key:'workshop-12',title:'Text-wide structural patterns and staging debate',scope:'Whole play · repetition, enclosure and renewed inquiry',summary:'Teaching lens: entrances, interruptions and revelations repeatedly alter authority within the room. The ending returns to an inquiry pattern after an attempted recovery of security. Compare repetitions through what changes rather than assuming repetition means identical circumstances.',
cards:[['Choose a pattern with a change to explain','Track two interruptions or revelations in the full play. Record what each interrupts, who gains authority and what becomes known. A structural claim needs more than noticing recurrence: explain how a later instance changes the audience’s understanding or places an earlier confident response under new pressure.'],['Relate enclosure to dramatic pressure','The room keeps participants and reactions in a shared dramatic space while accounts reach outside it. That arrangement can make evasion and confrontation visible. A production might emphasise distance or confinement, but a particular camera movement, soundtrack or modern set is a proposed staging choice unless actually specified in the script.'],['Debate the ending without closing the puzzle falsely','The final call can renew scrutiny after apparent escape. Compare a staging that stresses shock with one that stresses repetition and accountability. Defend the difference through text and sequence; neither production possibility proves a single identity for the Inspector or authorises ignoring unresolved details.']],details:[['Interruption','Identify the particular action or claim being redirected.'],['Shared room','Consider how reactions remain visible within a confined encounter.'],['Renewed inquiry','Explain repetition through changed expectations and stakes.']],people:[['Participants','Face questioning alongside others’ reactions.'],['Director','Makes choices within and beyond prescribed stage conditions.'],['Audience','Reassesses earlier claims as the inquiry returns.']],movement:[['Map','Choose two comparable interruptions.'],['Compare','Name the changed knowledge or authority.'],['Stage','Propose and label a production emphasis.'],['Judge','Test the ending’s effect without solving identity by assertion.']],challenge:['Which structural argument explains recurrence?','The inquiry pattern returns after apparent escape, changing the pressure on responsibility.','Every repeated event has identical circumstances and effects.','A preferred soundtrack proves a single identity in the script.','A pattern matters through its relation to changed stakes.','Explain what the later instance does differently in its context.'],practice:[['What should an interruption map record?','What is interrupted and how authority or knowledge changes.','Only a count of entrances with no function.','An assumption all interruptions prove dishonesty.','Structure is the organisation of action and information.','structure'],['Which staging statement is honest?','A camera emphasis is a production possibility unless prescribed.','Every camera angle is printed in the stage play.','A director can replace textual evidence with an invented quotation.','Keep written evidence distinct from a proposed realisation.','performance'],['Why debate different endings in performance?','Different emphases can be tested against the same sequence.','Every staging proves every other interpretation impossible.','The text has no role once lighting is chosen.','Interpretive choices still need evidence and limits.','interpretation']],check:[['What makes a repeated inquiry significant?','Its changed context tests the attempted restoration of security.','It guarantees nothing has changed between moments.','It proves every question has one settled answer.','Recurrence and difference need to be analysed together.','meaning'],['What does the room’s arrangement help analyse?','The visibility of reactions, confrontation and attempts to evade.','A literal claim that no outside world exists.','An exact building plan for every production.','A shared dramatic space can shape pressure and attention.','methods'],['Which claim overstates a production choice?','A soundtrack proves the Inspector’s identity beyond dispute.','A pause may stress shock at the call.','A repeated visual arrangement may recall the opening.','Staging can support an emphasis without verifying an unresolved identity.','limits'],['What makes a fair staging debate?','Defend alternatives through text, sequence and qualified effects.','Choose one based solely on personal taste.','Invent directions that remove every uncertainty.','A performance argument remains an evidence-based interpretation.','argument']],writing:'How does a repeated structural pattern create renewed pressure? Compare two moments and defend two possible staging emphases for the ending, distinguishing script evidence from additions.',rubric:['Explain recurrence through a precise change in knowledge, authority or stakes.','Connect shared stage conditions with dramatic pressure rather than a literal building plan.','Defend alternative staging choices while preserving textual limits and uncertainty.']}),
make({topic:'inspector',key:'workshop-13',title:'Timed modern-text argument assessment',scope:'Whole-play preparation and independent argument',minutes:50,summary:'Teaching lens: a plan about Eva’s represented voice can practise moving from a precise account to a whole-play judgment. The independent task asks a different question about reputation and responsibility and supplies no extract.',
cards:[['Prepare a transferable argument method','Choose a particular account of Eva and practise explaining who tells it, what is selected and what remains uncertain. This helps turn a reference into an argument rather than a plot list. The independent task has a different focus, so a prepared paragraph must be reconsidered instead of pasted into any question.'],['Plan around the actual question','For a whole-play task, choose a thesis that answers the question and select moments that develop or test it. Explain how language, dramatic action or structure supports each claim. Context belongs where it illuminates a detail, and an awkward example should refine the argument rather than be quietly omitted.'],['Preserve independent performance honestly','Aim for about 45 minutes including planning and checking; timing is advisory, not enforced. No extract is supplied for this original whole-play practice. Guidance and criteria remain hidden until the first submission, which is preserved separately from revisions. Writing is saved for review and receives no automatic essay mark.']],details:[['Claim','Answer the actual focus rather than a memorised theme.'],['Reference','Locate a moment and explain the relevant dramatic choice.'],['Qualification','Use a challenging example to refine the judgment.']],people:[['Preparing writer','Practises a flexible method on a different focus.'],['Independent writer','Selects evidence for the whole-play question.'],['Later reviewer','Uses the preserved response to identify a real revision priority.']],movement:[['Plan','Write a relevant thesis and route through evidence.'],['Analyse','Explain particular choices, not only events.'],['Test','Consider a moment that complicates the claim.'],['Check','Review accuracy, relevance and expression before submission.']],challenge:['Which preparation transfers to a new whole-play focus?','Adapt a claim and evidence route to the actual question.','Paste a fixed essay regardless of the question.','Assume every theme requires exactly the same examples.','A method transfers when its application responds to the task.','Check whether the selected moment answers this question.'],practice:[['What makes a whole-play reference useful?','It develops or tests a relevant argument.','It increases plot coverage without explanation.','It replaces any need to discuss a method.','A reference needs a function in the reasoning.','argument'],['What is the status of the suggested time?','An advisory practice budget, not an enforced deadline or official paper.','An automatic grade awarded at 45 minutes.','A guarantee every learner works at the same pace.','The conditions must be described honestly.','conditions'],['What should checking improve?','Evidence accuracy, sentence control and relevance to the question.','The number of invented quotations in the response.','An unrelated paragraph solely to increase length.','Editing should strengthen the argument and its expression.','editing']],check:[['What determines the evidence selection?','The actual whole-play question and a relevant line of reasoning.','Only the quotation easiest to remember.','A rule that all questions have the same answer.','Selection should serve the focus being assessed.','meaning'],['What should happen to awkward evidence?','Use it to test and qualify the thesis.','Remove it from the play by assertion.','Invent a speech that makes it disappear.','A sustained argument can explain its own limits.','evaluation'],['What is preserved after first submission?','The original response separately from later revisions.','An automatically assigned official examiner mark.','Only the latest draft with no record of the first.','The record supports review without pretending to mark attainment.','assessment'],['Which final edit is substantive?','Correct a misattribution and explain its link to the thesis.','Add unrelated dates instead of analysis.','Remove every qualification to sound certain.','Accuracy and relevance improve the reasoning.','editing']],writing:'Practise a brief plan about represented voices, then use the independent workspace for its different whole-play question.',rubric:['Sustain a relevant whole-play argument that answers the precise question.','Analyse accurate textual references through language, dramatic action or structure.','Test the thesis with a complicating moment and maintain controlled, qualified expression.'],extra:{independentWriting:true,independentTaskType:'whole-text',independentTaskLabel:'Original whole-play practice with no supplied extract, not an official exam paper.',independentIntro:'Use your knowledge of the whole play; no extract is supplied. Aim for about 45 minutes including planning and checking. Timing is advisory, not enforced.',independentPrompt:'How does Priestley present tensions between reputation and responsibility in An Inspector Calls? Develop a whole-play argument using precise references and analysis of dramatic methods.',independentExtractLabel:'Whole-play argument · no supplied extract',independentExtract:''}}),
make({topic:'inspector',key:'workshop-14',title:'Feedback-led modern-text redraft and delayed recall',scope:'Whole-play writing · diagnose, revise and retrieve later',summary:'Teaching lens: a revised argument should address a specific weakness in the original response. Bringing an assessment forward keeps the first submission intact; later retrieval tests remembered evidence separately from immediate familiarity.',
cards:[['Diagnose from the actual response','Bring your first whole-play assessment into this workshop if it is saved here, or use a draft you already have. Compare the writing with the criteria and any real teacher feedback. Choose one unsupported claim, inaccurate reference or weak connection. No mark or teacher comment is fabricated by the app.'],['Change the reasoning that needs work','If an argument equates avoiding scandal with accepting responsibility, test it against a later response that distinguishes those priorities. Revise the claim or the explanation of the evidence. A substantive redraft addresses the diagnosed weakness; replacing words with longer synonyms does not by itself improve the argument.'],['Retain versions and return after time','Save the changed version and note why it is stronger or more accurate. The original independent response stays separate. Return later to retrieve an exact reference or honest paraphrase before checking the source. Immediate completion and saved versions are useful records, but neither proves durable recall or essay mastery.']],details:[['Diagnosis','Identify a specific weakness in the actual reasoning.'],['Revision','Change the claim-evidence relation to address that weakness.'],['Later retrieval','Test a remembered reference after an interval, then verify it.']],people:[['First-response writer','Provides the original reasoning to review.'],['Reviewer','Uses criteria and feedback actually received.'],['Revising writer','Retains the earlier version and explains a substantive change.']],movement:[['Diagnose','Name the actual gap.'],['Revise','Address it through verified evidence and explanation.'],['Compare','Save a version and explain the difference.'],['Return','Retrieve later without treating familiarity as accuracy.']],challenge:['Which change improves reasoning?','Distinguish concern for scandal from accepting responsibility using a verified exchange.','Invent an examiner’s mark to make the draft look complete.','Only change the font while keeping the same unsupported claim.','The revision should respond to a demonstrated weakness.','Ask what the edit changes in the claim-evidence relation.'],practice:[['Where should a revision priority come from?','The actual writing, criteria and real feedback if available.','A fabricated comment from an examiner.','An unrelated random edit.','Diagnosis needs evidence from the response being revised.','diagnosis'],['Why retain the first submission?','It permits comparison without silently replacing the original.','It guarantees full marks for every later version.','It prevents all learning after the assessment.','A record shows change without promising its quality.','versions'],['What makes later retrieval a different test?','Attempt evidence after an interval before reopening the source.','Reread immediately and declare permanent mastery.','Assume confidence alone proves wording exact.','Delay and source verification test more than familiarity.','recall']],check:[['What does bringing in an assessment do?','Copy the first response to an empty draft while leaving the source unchanged.','Overwrite the source assessment automatically.','Create an official essay mark from knowledge scores.','The original and the redrafting workspace remain distinct.','meaning'],['Which edit addresses a weak connection?','Explain how the selected exchange supports the actual thesis.','Append a new quotation without any relation.','Replace evidence with an imagined grade.','A stronger relation matters more than added length.','argument'],['Which review claim is honest?','Self-review or teacher feedback actually received can guide the edit.','Every draft has already received specialist marking.','Saving proves an examiner approves every sentence.','Do not substitute invented authority for actual review.','review'],['What remains to be tested later?','Accurate retrieval and application after time has passed.','Whether clicking Save makes forgetting impossible.','Whether a knowledge check proves independent essay quality.','Learning over time needs later evidence.','retention']],writing:'Bring in your first assessment if available, diagnose one real weakness and redraft the relevant section. Save a version and explain the substantive change.',rubric:['Identify a specific weakness from the actual writing and any real feedback.','Strengthen the relation between a claim, verified evidence and explanation.','Compare versions honestly and plan delayed retrieval without claiming an automatic mark.'],extra:{revisionFrom:'lit.inspector.workshop-13'}}),
make({key:'workshop-01',title:'Ozymandias and My Last Duchess comparative argument',scope:'Ozymandias / My Last Duchess · who controls representation?',summary:'Teaching lens: Shelley presents a ruler through a reported encounter with a damaged monument. Browning presents a Duke directing an encounter with a portrait. Compare how each ruler’s desire to control a representation is exposed by the poem’s form and framing.',
cards:[['Compare a relation rather than a label','Both poems connect authority with representation, but they do so through different voices and objects. A broken monument reaches the reader through reports, while the Duke speaks within a social encounter. Begin with that relation instead of writing that both men are powerful and then treating the poems as identical.'],['Let form complicate control','In Ozymandias, the ruined setting tests a boast through the gap between inscription and what survives. In My Last Duchess, the Duke’s managed account can expose values he does not intend to criticise. Analyse how mediation or dramatic monologue limits a ruler’s control over the interpretation of his own display.'],['Build a qualified comparative judgment','Compare one precise method in each assigned text, then explain a significant difference in what undermines authority. Do not identify either ruler automatically with his poet. A strong argument can show representation outlasting or exposing power without claiming the same historical situation, form or moral effect in both poems.']],details:[['Reported monument','Trace how the reader receives the ruler’s claim indirectly.'],['Managed portrait encounter','Ask how the Duke directs attention and presents himself.'],['Uncontrolled interpretation','Consider what readers can judge beyond the ruler’s intended display.']],people:[['Ruler represented','Attempts to define status through an object and account.'],['Mediating voice','Frames how that representation reaches a listener.'],['Critical reader','Tests the claim against framing, form and what is disclosed.']],movement:[['Relate','State the shared question about represented authority.'],['Analyse Shelley','Explain how ruin tests the boast.'],['Analyse Browning','Explain how the Duke’s speech exposes his values.'],['Judge','Develop a difference in how control is limited.']],challenge:['Which comparison explains a significant difference?','Ruin tests one ruler’s boast, while another ruler’s managed speech exposes his values.','Both poems have exactly the same speaker and narrative form.','The poets personally approve every claim made by the rulers.','A useful comparison explains different mechanisms within a shared question.','Compare how the authority is tested, not just whether it exists.'],practice:[['What makes a comparison relational?','A shared question is developed through methods in both texts.','Two separate summaries are placed beside each other without a link.','Every difference is removed to make the poems match.','The relation should do argumentative work.','comparison'],['How can dramatic monologue expose control?','A speaker’s managed account can reveal values beyond the intended impression.','It always makes the speaker identical to the poet.','It guarantees every statement is factually complete.','The form permits a reader to judge the act of telling.','methods'],['Which distinction matters to Ozymandias?','The ruler’s claim differs from the ruined evidence surrounding it.','The inscription proves every work still stands intact.','There is no mediation between ruler and reader.','Framing can test the authority a statement seeks to project.','framing']],check:[['What is the shared comparative question here?','How rulers try to control representation and how that control is limited.','Whether the poems have identical settings and forms.','Which poet owns a literal palace today.','A focused relation makes differences relevant.','meaning'],['Which method belongs to the Duke’s presentation?','A managed speaking encounter that readers can evaluate critically.','An unmediated confession by Browning about his own marriage.','A guarantee that no listener can question the account.','Speaker, poet and reader judgment remain distinct.','voice'],['Which claim overstates similarity?','Both rulers are exposed through exactly the same form and situation.','A display can reveal more than its owner intends.','Mediation affects how authority reaches a reader.','Shared concern does not mean identical construction.','limits'],['What should a conclusion explain?','A significant difference in how representation tests power.','Only repeat that both poems have a ruler.','Rank the poems without using methods or evidence.','A judgment should emerge from the compared mechanisms.','argument']],writing:'Compare how Shelley and Browning expose a ruler’s desire to control representation. Analyse a precise method in each assigned poem and develop a significant difference.',rubric:['Sustain a shared question about authority rather than two disconnected summaries.','Analyse mediation or form accurately in each poem with precise references.','Explain a significant difference while distinguishing speakers from poets.']}),
make({key:'workshop-02',title:'London and Checking Out Me History voices and authority',scope:'London / Checking Out Me History · public authority and knowledge',summary:'Teaching lens: Blake’s city observer registers repeated signs of suffering and constraint. Agard’s speaker challenges a received account of history and develops an alternative sense of identity. Compare the voices’ relations to authority without assuming identical responses.',
cards:[['Choose an exact shared focus','Both poems can be read through authority over people’s lives, but the forms of control differ. London connects observation with public institutions and repeated suffering; Checking Out Me History contests the selection of knowledge. Frame a comparison that explains those differences rather than treating every form of authority as interchangeable.'],['Analyse patterns in relation to voice','Read repeated structures and shifts in each assigned text. Ask what is accumulated, what is contrasted and whose version is being challenged. A pattern in one poem may intensify constraint while a contrast in another makes alternative knowledge visible. Do not assume every repetition automatically produces the same emotional or political effect.'],['Compare the possibilities of response','Agard’s speaker can be read as actively reconstructing identity, while the city observer’s repeated encounters may offer a different position on resistance. Test that judgment through precise evidence and acknowledge complication. Neither voice should be converted into a complete biography of its poet or an authoritative account of every reader’s history.']],details:[['City observation','Trace how repeated encounters present constraint.'],['Selected history','Identify what account the speaker contests.'],['Alternative knowledge','Explain how a structural contrast can support resistance.']],people:[['Blake’s observer','Connects sights and sounds with a judgment of the city.'],['Agard’s speaker','Questions a received selection of history.'],['Reader','Compares different capacities to challenge authority.']],movement:[['Focus','Define the particular authority being compared.'],['Pattern','Analyse how each voice organises its evidence.'],['Contrast','Explain differences in resistance or constraint.'],['Qualify','Test the judgment against a complicating detail.']],challenge:['Which comparison is method-led?','Explain how accumulation in one voice and contrasting knowledge in another shape responses to authority.','State both poems mention power and stop there.','Assume every repeated phrase has an identical effect.','Methods create the specific relation between a voice and authority.','Name what each pattern accumulates or contrasts in its own text.'],practice:[['What is challenged in Agard’s poem?','A received selection of historical knowledge and its effect on identity.','A guarantee that every history is equally complete.','Only the physical shape of a city street.','Locate the particular object of the speaker’s challenge.','focus'],['What should repetition analysis explain?','What is accumulated or contrasted in this voice and context.','A fixed effect that applies to every repetition in poetry.','Only how many letters recur.','A pattern’s work needs to be interpreted locally.','methods'],['Which comparison needs qualification?','The voices have different possibilities for responding to authority.','The two poems must have identical forms of resistance.','Both speakers are necessarily literal biographies of their poets.','Difference should be supported rather than assumed away.','interpretation']],check:[['What makes the shared focus precise?','It distinguishes public constraint from authority over historical knowledge.','It calls every kind of power identical.','It ignores what each voice actually challenges.','A focused comparison can include meaningful differences.','meaning'],['Which use of terminology is analytical?','Connect a repeated structure to the particular account of constraint.','Name repetition without explaining its work.','Assume repetition always means joy.','The term should support a local interpretation.','methods'],['Which speaker claim is unsafe?','A poetic voice supplies a complete verified biography of the poet.','A speaker can challenge a received account.','A reader can consider contrasts in knowledge.','Voice and biographical author are not automatically identical.','limits'],['What strengthens the comparative judgment?','A precise difference in how each voice can challenge authority.','A list of shared nouns without analysis.','Two independent essays with no reasoning between them.','Explain a relation rather than merely sharing a theme.','argument']],writing:'Compare how voices respond to authority in London and Checking Out Me History. Explain a pattern in each and a qualified difference in the possibility of resistance.',rubric:['Define the shared authority question while preserving its different forms.','Analyse a precise verbal or structural pattern in each assigned text.','Develop a qualified difference in response without equating speaker and poet.']}),
make({key:'workshop-03',title:'Prelude and Storm on the Island nature comparison',scope:'The Prelude extract / Storm on the Island · perceived power',summary:'Teaching lens: a remembered solitary encounter in The Prelude can be compared with a collective account of exposure in Storm on the Island. Consider how perspective, imagery and organisation present nature’s power without treating perceived intention as a verified motive.',
cards:[['Keep the perspectives distinct','The Prelude extract recalls a particular experience through a later telling voice. Storm on the Island presents a collective position facing exposure. Compare what those perspectives let a reader know about confidence, disturbance and memory. A shared concern with nature does not make the situations or voices identical.'],['Read apparent agency as presentation','In each assigned text, choose an image that makes natural power seem active or threatening. Explain how perception and figurative language shape that impression. Do not treat a mountain or weather as having a scientifically verified human motive merely because a speaker’s language gives it apparent purpose.'],['Compare how disturbance develops','Trace a change from confidence or preparation towards unease, and distinguish an immediate encounter from effects carried into recollection. A supported comparison can explain the limits of human control while recognising differences in timescale and community. Nature is not simply a single fixed symbol with one compulsory meaning in both poems.']],details:[['Retrospective voice','Distinguish the remembered experience from the later telling.'],['Collective position','Consider what speaking as a group changes.'],['Apparent agency','Interpret an image without converting it into a literal human motive.']],people:[['Remembered individual','Experiences an encounter whose meaning develops in memory.'],['Exposed community','Presents a collective relation to conditions.'],['Reader','Tests how perspective shapes the perceived power of nature.']],movement:[['Locate','Identify who speaks and when the experience is told.'],['Analyse','Explain an image of apparent power.'],['Trace','Follow disturbance across the text’s organisation.'],['Compare','Develop a difference in perspective and timescale.']],challenge:['Which nature reading keeps perception and fact distinct?','Figurative agency can present felt threat without proving a natural object has a human motive.','Every threatening image verifies nature’s literal intention to punish.','A shared natural setting means identical voices and experiences.','A speaker’s perception is important without becoming scientific proof of intention.','Identify the figurative presentation and the perspective behind it.'],practice:[['What does retrospective mean here?','A later voice recounts an earlier encounter.','Every event is narrated before it can happen.','No relationship exists between experience and memory.','The time of telling can shape interpretation of an event.','voice'],['Why compare collective and individual positions?','They offer different relations between confidence, exposure and response.','They prove every speaker has the same experience.','They make imagery irrelevant to nature.','Perspective is part of the construction of power.','methods'],['Which claim should be qualified?','Nature seems purposeful through the speaker’s imagery.','A mountain has a verified human political plan.','Weather literally explains its intentions to all characters.','Apparent agency is a presentation to analyse, not a fact to invent.','limits']],check:[['Which difference matters to perspective?','A remembered individual encounter differs from a collective account of exposure.','Both poems necessarily have the same narrator and situation.','Neither poem has any shaped perspective.','A common theme can be constructed through distinct voices.','meaning'],['What should image analysis establish?','How a particular choice makes power seem active or threatening.','Only that the poem contains a natural object.','An exact scientific motive of the weather.','Explain the effect of a textual choice in context.','methods'],['What does a structural comparison trace?','How confidence or preparation is disturbed over the course of each text.','Only the total number of landscape nouns.','A universal rule that all endings mean defeat.','Organisation shapes the development of a response.','structure'],['What makes the judgment qualified?','Explain perceived power and limits of control while preserving different timescales.','Assign one identical meaning to nature everywhere.','Treat a speaker’s image as a literal confession by a mountain.','Use the evidence at the level it supports.','argument']],writing:'Compare how perceived natural power disturbs human confidence. Analyse perspective and a precise image in each text, then explain a difference in how the disturbance develops.',rubric:['Distinguish retrospective individual and collective perspectives accurately.','Analyse figurative power without inventing literal natural motives.','Compare development and timescale through specific structural evidence.']}),
make({key:'workshop-04',title:'Exposure and Charge of the Light Brigade conflict comparison',scope:'Exposure / The Charge of the Light Brigade · waiting and movement',summary:'Teaching lens: Owen’s organisation of waiting and recurring frustration can be compared with Tennyson’s presentation of movement and collective commemoration. Both concern suffering in conflict, but their forms of attention and public address differ.',
cards:[['Make a distinction within a shared concern','Both poems can invite attention to the cost of conflict. Exposure’s repeated waiting differs from the forward motion and retrospective public commemoration in The Charge of the Light Brigade. Begin by explaining that contrast instead of assuming that a war theme automatically produces one attitude or one type of voice.'],['Connect organisation with experience','Read the recurring endings in Owen and the rhythmic or repeated patterns in Tennyson. Explain how time, expectation and collective action are shaped by the actual pattern. Regularity does not automatically mean approval of command, and disrupted movement does not by itself prove every speaker has the same political position.'],['Qualify the public judgment','Tennyson can commemorate courage while allowing criticism of an order; Owen can emphasise suffering without becoming only a catalogue of facts. A comparative argument should explain what each organisation asks a reader to attend to. Do not assume either poem is an unmediated personal diary simply because it concerns soldiers.']],details:[['Waiting','Trace how deferred action shapes time and expectation.'],['Movement','Explain the pattern presenting collective advance.'],['Commemoration','Distinguish honouring participants from endorsing every order.']],people:[['Waiting soldiers','Experience conflict through endurance and frustrated expectation.'],['Commemorated group','Becomes the focus of a public account of courage and cost.'],['Reader','Judges how the forms direct attention and sympathy.']],movement:[['Relate','Define the shared question about conflict’s cost.'],['Analyse time','Explain waiting or forward movement.'],['Test attitude','Separate courage from endorsement of decisions.'],['Judge','Compare different forms of attention to suffering.']],challenge:['Which claim avoids a false choice?','A poem can honour courage while exposing the cost of a damaging order.','Commemoration automatically approves every decision in a conflict.','Regular rhythm always proves the poet enjoys violence.','Commemoration and critical judgment can coexist.','Distinguish the people honoured from the decisions that expose them to harm.'],practice:[['What does comparing waiting and movement add?','It explains different organisations of experience and time.','It proves the poems have identical structures.','It replaces the need for any exact reference.','A structural distinction can develop a shared theme.','structure'],['How should rhythm be interpreted?','Through its local relation to action, voice and meaning.','By a fixed rule that regularity always means approval.','Only by counting syllables with no interpretation.','Pattern requires a contextual account of its work.','methods'],['Which assumption should be resisted?','A soldier-focused poem is necessarily the poet’s unmediated diary.','A poem can commemorate a group.','Waiting can shape a reader’s experience of time.','Poetic voice and autobiographical author remain distinct.','voice']],check:[['What is the central structural contrast here?','Repeated waiting and frustrated expectation versus organised collective movement.','Identical action and timing in both poems.','The absence of any shaped organisation.','A shared concern can develop through different temporal patterns.','meaning'],['Which judgment is compatible with commemoration?','Courage may be valued while a damaging order remains open to criticism.','All military decisions must therefore be praised.','Human cost can never be mentioned.','Keep respect for participants distinct from approval of every command.','interpretation'],['What makes a rhythm point analytical?','Explain how the pattern shapes action or attention in that poem.','State regular means happy without considering the text.','Use a term that cannot be located in the lines.','Terminology should explain an actual pattern’s work.','methods'],['Which conclusion is sustained?','Compare how the different organisations direct attention to conflict’s cost.','Only repeat that both poems concern soldiers.','Treat all war voices as identical biographies.','An argument needs a relation between methods and judgment.','argument']],writing:'Compare how the poems make the costs of conflict significant through waiting and movement. Analyse one structural pattern in each and qualify the relation between courage and criticism.',rubric:['Explain a precise contrast in the organisation of time and action.','Analyse rhythm or repetition locally without a fixed automatic effect.','Develop a qualified judgment that distinguishes commemoration from endorsement.']}),
make({key:'workshop-05',title:'Bayonet Charge and Remains trauma comparison',scope:'Bayonet Charge / Remains · fear, uncertainty and aftermath',summary:'Teaching lens: immediate action under threat in Bayonet Charge can be compared with a remembered episode and its continuing pressure in Remains. Analyse how narration and uncertainty shape experience without using a poem as a clinical case record.',
cards:[['Locate the experience and time of telling','Bayonet Charge presents a soldier within immediate movement and threat, while Remains moves through an account of an episode and its persistence. Trace what is happening now, what is remembered and how the account changes. A comparison needs those distinctions rather than a general claim that both speakers simply feel bad.'],['Analyse uncertainty and return','Choose a precise moment of doubt, repeated memory or disrupted thought in each assigned text. Explain how tense, pronoun or structural recurrence shapes the relation between action and reflection. Do not assume that every uncertainty means dishonesty, or that the poet and the represented soldier must be the same person.'],['Keep the interpretation proportionate','The poems can invite attention to fear, responsibility and lasting distress. They do not provide sufficient evidence for a reader to issue a clinical diagnosis from a line. A strong comparison explains how different narrative choices make distress perceptible while preserving the ethical questions and limits of knowledge within the account.']],details:[['Immediate threat','Locate the soldier’s relation to action and danger.'],['Recurrent memory','Trace how an event remains active in the telling.'],['Uncertainty','Explain its specific wording without treating doubt as automatic dishonesty.']],people:[['Figure in immediate action','Faces danger amid movement and disrupted reflection.'],['Remembering speaker','Revisits an episode whose pressure persists.'],['Reader','Compares represented distress without diagnosing a person.']],movement:[['Locate','Distinguish action from later telling.'],['Analyse','Explain uncertainty through a precise verbal choice.'],['Trace','Follow recurrence or after-effects structurally.'],['Qualify','Compare distress without a clinical verdict.']],challenge:['Which comparison stays within literary evidence?','Explain how narrative choices present fear and persistent distress without issuing a clinical diagnosis.','Diagnose a real person from one line of poetry.','Assume every uncertain account must be a deliberate lie.','The task is to analyse representation and its limits.','Connect a method to the experience presented rather than inventing a diagnosis.'],practice:[['Why distinguish immediate action from recollection?','The relation changes how fear, responsibility and aftermath are presented.','Both texts must therefore use identical narration.','Remembering automatically makes every account false.','Time of telling is a method with interpretive consequences.','voice'],['What can structural recurrence do?','Make an episode’s continuing pressure perceptible.','Guarantee a particular clinical diagnosis.','Prove the poet personally performed every narrated act.','A formal pattern can present persistence without a medical verdict.','methods'],['Which reading of uncertainty is too automatic?','Doubt always proves deliberate dishonesty.','Uncertainty can shape ethical reflection.','A reader should identify what remains unsettled.','Its meaning depends on wording, position and context.','limits']],check:[['Which distinction supports this comparison?','An immediate experience of threat differs from an event’s persistence in recollection.','All fear is presented through the same tense and voice.','The poems have no relation between action and thought.','Compare specific constructions rather than a shared feeling label.','meaning'],['What should a tense point explain?','How time and perspective affect the account of action or aftermath.','Only whether a verb is short or long.','A fixed emotion attached to every past tense.','A grammatical observation needs interpretive work.','methods'],['Which claim exceeds the evidence?','One poetic line establishes a definitive clinical diagnosis.','Repeated memory can present distress.','An account can leave a motive uncertain.','Literary representation is not a complete clinical record.','accuracy'],['What strengthens the final judgment?','Relate narrative differences to fear, responsibility and continuing pressure.','Ignore the methods and list plot events.','Treat represented soldiers as automatically identical to their poets.','A qualified judgment follows the analysed relation.','argument']],writing:'Compare the presentation of immediate fear and continuing distress in the poems. Analyse narrative time and a precise uncertainty or recurring pattern, without making a clinical diagnosis.',rubric:['Distinguish immediate action, recollection and time of telling accurately.','Explain a specific verbal or structural choice in each assigned poem.','Keep a qualified literary judgment separate from diagnosis or assumed autobiography.']}),
make({key:'workshop-06',title:'Poppies and War Photographer distance and memory',scope:'Poppies / War Photographer · private memory and public witnessing',summary:'Teaching lens: a parent’s remembered separation in Poppies can be compared with professional witnessing and the circulation of images in War Photographer. Physical distance does not necessarily mean emotional detachment; examine how each poem organises attention.',
cards:[['Specify the kinds of distance','A parent’s separation from a child differs from the photographer’s movement between conflict and a distant public. Both allow a question about memory and emotional proximity, but neither should be collapsed into the other’s situation. Identify who speaks or is presented, who is absent and how the reader receives the experience.'],['Analyse the organisation of memory','Read a precise sensory detail or shift in attention in each assigned text. Explain how ordinary objects, remembered contact or the processing of images connects a distant event with present experience. Do not merely name imagery: show what the detail makes present and whose access it permits or limits.'],['Develop a qualified public-private comparison','A private relationship and a professional role can each involve intense feeling. Compare what happens when experience is remembered or presented to others, and test a simple claim that distance means indifference. The poem’s voice or represented figure is not automatically a complete autobiographical account of its poet.']],details:[['Private separation','Identify the relation through which absence is felt.'],['Professional witnessing','Consider responsibility and limits in representing events to others.'],['Sensory memory','Explain how a detail brings an absent experience into the present.']],people:[['Parent figure','Experiences separation through a particular relationship.'],['Photographer figure','Mediates suffering across a distance to a public.'],['Reader or public','Encounters a shaped account rather than direct access to every event.']],movement:[['Distinguish','Locate the different roles and absences.'],['Analyse','Explain a sensory detail or transition.'],['Relate','Connect memory with present attention.'],['Judge','Test the equation of distance with indifference.']],challenge:['Which comparative claim is qualified?','Different forms of distance can coexist with intense feeling and responsibility.','Physical distance always proves emotional indifference.','A professional role removes every ethical concern.','Distance is a relation to analyse, not an automatic verdict about feeling.','Use the specific memory or image process to test the claim.'],practice:[['Why distinguish parent and professional roles?','They shape different kinds of access, absence and responsibility.','They prove the poems have identical speakers.','They make all memory impossible.','A shared focus becomes precise through different positions.','perspective'],['What should a sensory-detail point explain?','How the detail makes an absent experience present to a particular perspective.','Only that the poem names an object.','A guaranteed identical emotion for every reader.','Explain the work of the chosen detail in context.','methods'],['Which author claim is unsafe?','The represented role must be a complete literal autobiography of the poet.','A poem can explore professional witnessing.','A private relationship can shape memory.','A poetic construction does not automatically provide complete biography.','limits']],check:[['What is the useful distinction in distance?','Private separation differs from mediation between conflict and a public.','Every absence means exactly the same relationship.','All observers directly experience every event.','Compare the different relations that make memory significant.','meaning'],['How can a shift in attention contribute?','It connects a remembered or distant experience with the present scene.','It guarantees that every memory is an independently verified record.','It makes organisation irrelevant.','Sequence shapes how experience reaches the reader.','structure'],['Which inference overstates distance?','Being physically far away necessarily means caring less.','Distance can create limits in access.','A role can involve responsibility towards represented people.','Emotional relation needs textual evidence rather than a universal rule.','interpretation'],['What develops the comparison?','Explain how different roles organise memory and present feeling.','Write two unrelated character summaries.','Assume the title provides all evidence needed.','A relation between methods gives the shared focus depth.','argument']],writing:'Compare how distance and memory shape feeling in Poppies and War Photographer. Analyse a precise detail and a change of attention in each, preserving the different roles.',rubric:['Distinguish the kinds of separation, access and responsibility in the poems.','Explain sensory detail or organisation as a method rather than a label.','Test a qualified relation between distance and feeling without assuming autobiography.']}),
make({key:'workshop-07',title:'Kamikaze and The Emigree belonging and loss',scope:'Kamikaze / The Émigree · memory, voice and exclusion',summary:'Teaching lens: a family’s retelling of a pilot’s return in Kamikaze can be compared with a speaker’s attachment to a remembered city in The Émigree. Belonging is shaped through mediated voices, remembered images and pressures of exclusion.',
cards:[['Track whose memory reaches the reader','Kamikaze frames a return through family telling rather than giving unrestricted access to the pilot’s mind. The Émigree presents a speaker’s relation to a remembered place amid later pressure. Identify the layers of voice before treating every image as first-hand evidence or a verified geographical report.'],['Compare belonging through its loss','Read how family or community responses can exclude someone, and how remembered place can sustain an identity. The two poems do not need identical causes or outcomes to illuminate a shared question. Explain one significant difference in how a relationship to home is maintained, contested or withheld.'],['Qualify the knowledge of motives','A retold motive and an idealised memory can be meaningful without being fully verified facts. Test a claim through the poem’s framing, qualifiers and shifts in perspective. Avoid making either speaker a complete biography of the poet or treating all images of a city as a literal description of a named country.']],details:[['Family retelling','Separate reported interpretation from direct access to the pilot.'],['Remembered city','Consider how attachment shapes the presented image.'],['Exclusion','Compare how belonging can be withheld or sustained.']],people:[['Family teller','Mediates a return and its consequences.'],['Attached city speaker','Holds a relation to a place through memory.'],['Reader','Tests belonging claims through framing and limits of knowledge.']],movement:[['Attribute','Identify who tells and whose experience is represented.'],['Analyse','Explain a memory image or perspective shift.'],['Compare','Distinguish forms of exclusion and attachment.'],['Qualify','Avoid converting inferred motives into certainty.']],challenge:['Which reading respects mediated knowledge?','A family’s account can interpret a return without giving direct access to every motive.','Every reported thought is necessarily an independently verified fact.','A remembered city must be a literal map of a named country.','Framing shapes how much the reader can know.','Identify the teller and any qualification in the account.'],practice:[['Why track layers of voice?','They establish how a person’s experience reaches the reader.','They prove every image is an objective record.','They make all interpretations equally unsupported.','Attribution matters to what an inference can claim.','voice'],['What makes a belonging comparison precise?','Explain a difference in how attachment is sustained or withheld.','Assume both poems have identical causes and outcomes.','Only list that both contain memory.','A shared question needs a significant relational difference.','comparison'],['Which claim needs qualification?','A remembered place may be shaped by attachment and idealisation.','Memory gives a guaranteed complete geographical survey.','A retelling verifies every private motive.','An image can carry meaning without being a full factual map.','limits']],check:[['What should a Kamikaze voice analysis distinguish?','The represented pilot’s experience and the family account that mediates it.','The poet personally narrating an exact flight diary.','No difference between every teller and listener.','The framing is part of the account’s meaning and limits.','meaning'],['How can a city image be analysed responsibly?','Explain how the speaker’s attachment shapes its presentation.','Identify a country as certain without textual support.','Treat every metaphor as literal urban measurement.','A perspective presents a relation to place, not necessarily a verified map.','methods'],['Which comparison avoids a forced match?','Different forms of exclusion can test a shared question of belonging.','Both poems must have identical political circumstances.','All memories must refer to the poet’s own life.','A useful relation preserves historical and narrative differences.','interpretation'],['What supports a qualified judgment?','Use framing and a precise shift to limit claims about motives and memory.','Invent certainty where the text leaves a qualification.','Ignore who tells the account.','The strength of a reading depends on its handling of access and evidence.','argument']],writing:'Compare how voices and memory present belonging under pressure. Analyse a framing choice in Kamikaze and an image of place in The Émigree, qualifying what can be known.',rubric:['Attribute the layers of telling accurately and distinguish inference from confirmed information.','Analyse a precise memory image or perspective shift in each poem.','Develop a significant difference in belonging without inventing biography or geography.']}),
make({key:'workshop-08',title:'Tissue and Ozymandias fragile power comparison',scope:'Tissue / Ozymandias · materials, light and authority',summary:'Teaching lens: Tissue explores paper, light and human systems through extended figurative thinking. Ozymandias presents a damaged stone monument through a framed account. Compare how material images question durability without treating figurative building as a literal instruction.',
cards:[['Compare materials through their functions','Stone can suggest permanence, yet Shelley’s monument is damaged and set within a wider landscape. Paper in Tissue is associated with records and human systems as well as fragility. Analyse what each material is made to do in the poem rather than assigning stone permanent power and paper no power at all.'],['Read figurative transformation accurately','Tissue develops ideas through changes in material, light and imagined construction. A metaphorical building is not a practical instruction to replace every wall with paper. Explain how the figurative movement tests rigidity or control, and distinguish that movement from the account of visible ruins in Ozymandias.'],['Develop a difference in the argument','One poem can question a ruler’s claim through what remains; another can imagine relations that are less fixed or enclosing. Support the difference through a precise image and structural relation in each. Fragility can expose limits without proving human systems have no consequences or power has vanished altogether.']],details:[['Stone monument','Read the relation between an intended permanence and damage.'],['Paper systems','Consider how fragile material can still record and organise lives.'],['Light and transformation','Analyse a figurative possibility without literalising construction.']],people:[['Monument’s ruler','Seeks enduring authority through a representation.'],['Reflective paper voice','Explores relations between material systems and human life.'],['Reader','Compares limits of durability and different imagined alternatives.']],movement:[['Locate','Identify the material and its function.'],['Analyse','Explain a precise relation between durability and fragility.'],['Trace','Follow a shift in the poem’s organisation.'],['Judge','Compare the different ways authority is questioned.']],challenge:['Which reading avoids literalising metaphor?','An imagined paper construction can test rigidity without being a practical building instruction.','The poem orders all real buildings to be made only from paper.','Fragile records can never exercise any social power.','Figurative transformation carries an argument rather than a technical specification.','Explain what the material change suggests about human systems.'],practice:[['Why avoid a fixed material dictionary?','The function of stone or paper depends on its relation within the poem.','Stone always proves power can never fail.','Paper always means no human consequences.','Context and organisation determine an image’s work.','imagery'],['What distinction matters to the pair?','Visible ruin differs from an imagined figurative transformation.','Both poems necessarily describe the same building.','Every material image is a literal instruction.','The poems construct different kinds of evidence and possibility.','comparison'],['Which conclusion is too strong?','Fragility proves human systems have no power or consequences.','A record can organise life despite its material fragility.','A damaged monument can test a boast of permanence.','Limited durability does not mean an absence of effect.','limits']],check:[['What does the damaged stone help test?','An intended claim to lasting authority.','A guarantee every work survives untouched.','A literal modern engineering code.','The relation of claim and evidence matters to the image.','meaning'],['How should an imagined material change be analysed?','As figurative thinking about relations or rigidity in context.','As a compulsory practical construction manual.','As proof the poem has no argument.','Metaphorical presentation and technical instruction are distinct.','methods'],['Which material judgment needs qualification?','A fragile medium can still organise or affect human lives.','Fragility means all records are socially powerless.','Damage makes every historical consequence disappear.','Do not confuse durability with the existence of power.','interpretation'],['What strengthens the comparative conclusion?','Explain different ways the material relations question enduring control.','Repeat that both poems name an object.','Force one identical method and outcome onto both.','A shared focus should develop through specific differences.','argument']],writing:'Compare how material imagery questions the durability of power. Analyse a precise relation in Tissue and Ozymandias and explain a significant difference in their imagined possibilities.',rubric:['Interpret material images through their particular functions and contexts.','Distinguish figurative transformation from literal construction or visible ruin.','Compare limits of durability without equating fragility with no consequences.']}),
make({key:'workshop-09',title:'Choosing evidence for an unfamiliar comparison focus',scope:'Anthology · relevance, selection and a significant difference',summary:'Teaching lens: a new comparison focus changes which details are useful. Start with the exact question, choose a second assigned poem because its methods serve that focus, and explain a significant difference rather than selecting only familiar quotations.',
cards:[['Translate the focus into an evidence question','If asked about the effects of authority, ask what changes in people’s lives or perceptions, not merely where a ruler is named. Read the exact wording before selecting a partner poem. A remembered quotation may be accurate yet irrelevant if its function does not bear on the question being answered.'],['Choose a partner for an explained reason','Make a brief candidate comparison using a precise moment in each assigned text. Test whether the pair permits a useful difference as well as a shared concern. The most familiar poem is not automatically the strongest choice, but an unexpected choice still needs evidence rather than novelty for its own sake.'],['Build a flexible evidence route','Plan two or three related claims and select short references that develop them. Explain what each method does for the focus instead of listing every quotation you know. If a detail does not support the developing argument, replace it or explain a different role; do not silently change the question to fit your memory.']],details:[['Focus','Turn the actual question into something evidence can answer.'],['Partner choice','Defend the relation and an important difference.'],['Evidence route','Select details for the reasoning they make possible.']],people:[['Task setter','Defines a focus the response must address.'],['Comparing writer','Chooses a partner and an evidence route with reasons.'],['Critical reviewer','Tests relevance rather than rewarding quotation quantity.']],movement:[['Read','Identify the exact question.'],['Choose','Defend a second poem’s relevance.'],['Test','Look for a meaningful difference and awkward evidence.'],['Plan','Arrange details into a connected argument.']],challenge:['What makes a partner choice defensible?','Its methods support the exact focus and allow an explained comparative difference.','It contains the longest quotation the writer remembers.','It is unusual, so no evidence is needed.','Relevance is a relation between the task, the poems and the planned reasoning.','State why this pair helps answer this question.'],practice:[['When can an accurate quotation be unhelpful?','When its function has no explained relation to the question.','Only when it is shorter than ten lines.','Whenever the writer can identify its speaker.','Accuracy is necessary but does not replace relevance.','selection'],['Why seek a significant difference?','It develops the shared focus beyond a superficial match.','It proves the poems cannot be compared.','It requires changing the question to a different theme.','Difference can sharpen a comparative argument.','comparison'],['What should a plan organise?','Claims and details that develop a connected response to the focus.','All remembered quotations regardless of their function.','Two unrelated summaries with no argument.','A route should be shaped by the task rather than recall quantity.','planning']],check:[['What should happen before choosing a partner?','Read the exact focus and identify what evidence must explain.','Commit to a fixed essay without reading the question.','Assume every power question has one identical meaning.','Selection begins with the actual task.','meaning'],['Which evidence choice is strongest?','A precise detail whose method advances a relevant claim.','A long passage included only to display memory.','An invented line that makes the poems agree.','Evidence must work within the reasoning.','evidence'],['What does an unusual partner still need?','A supported relation and a meaningful difference.','No explanation because novelty proves quality.','A claim that every interpretation is equally valid.','Originality does not remove the need for evidence.','evaluation'],['What makes a comparative route coherent?','Each claim develops the question through a relation between both poems.','Each paragraph ignores the other poem entirely.','The response changes the task to suit one favourite quotation.','A sustained focus connects selection, methods and judgment.','argument']],writing:'Choose an anthology comparison focus that feels less familiar. Select two poems, justify the pair and plan a method-led argument with one significant difference and one detail you would reject as irrelevant.',rubric:['Define the precise focus before selecting a partner or quotation.','Defend a relation and significant difference through methods in both poems.','Explain why selected details advance the argument and reject an irrelevant detail honestly.']}),
make({key:'workshop-10',title:'Alternative readings and precise poetic terminology',scope:'Anthology · terms, counter-evidence and qualified judgment',summary:'Teaching lens: terms such as enjambment, caesura or dramatic monologue name features to locate and explain. They do not supply automatic emotions. Test two readings through actual wording and organisation before deciding what the evidence warrants.',
cards:[['Verify the feature before interpreting it','An enjambed line continues syntax across a line ending; a caesura is a pause within a line. Locate the actual wording and punctuation rather than assigning a term to every line break. A useful observation explains how the syntax or pause works at this moment, not a memorised rule that the feature always means panic.'],['Give an alternative its best evidence','For a speaker’s control or uncertainty, identify a precise detail that supports each possible reading. Do not make the rival obviously foolish through an invented quotation. A critical argument becomes stronger when it responds to a genuine tension and explains which reading accounts for more of the text.'],['Reach a proportionate judgment','Use form terms accurately and link them to voice, movement or attention. A sonnet does not automatically mean romantic love, and a dramatic monologue does not make its speaker the poet. Qualify an effect and show how counter-evidence refines your conclusion rather than treating disagreement as proof that evidence is unnecessary.']],details:[['Enjambment','Syntax continues across a line ending; check the actual continuation.'],['Caesura','A pause occurs within a line; explain its local function.'],['Form and voice','A named form shapes possibilities without dictating one universal meaning.']],people:[['First reader','Proposes a reading supported by a detail.'],['Alternative reader','Identifies a real tension or counter-example.'],['Critical judge','Uses accurate terms to explain which account is more convincing and why.']],movement:[['Locate','Verify the feature in the actual text.'],['Explain','Connect its local function to a claim.'],['Challenge','Test an alternative through fair evidence.'],['Qualify','Refine the judgment in response to the tension.']],challenge:['Which terminology point is analytical?','Locate a pause within a line and explain its effect on this voice at this moment.','Declare every caesura means panic regardless of context.','Call any line ending enjambment without checking the syntax.','The feature must be real and its function locally explained.','Verify the pattern before assigning an effect.'],practice:[['What distinguishes enjambment from a line ending alone?','The syntax continues across that ending.','Every printed line must end a complete sentence.','Enjambment is any capital letter.','Locate the relation between syntax and the line.','terminology'],['What makes an alternative fair?','It uses genuine relevant evidence rather than an invented weak rival.','It deliberately changes the poem’s words to lose.','It needs no evidence because it is different.','Critical comparison should test the strongest competing account.','alternatives'],['Which form claim is too automatic?','Every sonnet necessarily presents romantic love.','A form can shape a pattern of development.','A monologue creates a speaking situation to evaluate.','A form name does not dictate one theme or attitude.','limits']],check:[['What is a caesura?','A pause within a poetic line.','Every space between stanzas.','Any line that contains a natural image.','Define the feature accurately before using it analytically.','meaning'],['What makes a term useful in an argument?','It explains a real feature’s work in the specific passage.','It appears often even when it cannot be located.','It substitutes a fixed emotion for textual reasoning.','Terminology should serve an interpretation rather than replace one.','methods'],['How should counter-evidence be handled?','Use it to test and refine the scope of the claim.','Erase it by inventing a different line.','Accept all claims equally without examining support.','A proportionate judgment responds to what complicates it.','evaluation'],['Which speaker distinction matters?','A dramatic monologue’s speaker is not automatically its poet.','Every fictional speech is a complete literal autobiography.','Form makes all attribution irrelevant.','The speaking situation is constructed and can invite critical judgment.','voice']],writing:'Choose a passage from an assigned poem, locate one feature accurately and defend two possible readings. Use genuine counter-evidence to reach a qualified judgment.',rubric:['Use a precise term only for a feature actually present in the passage.','Explain a local function rather than attaching a universal emotion to a method.','Represent an alternative fairly and refine a judgment through counter-evidence.']}),
make({key:'workshop-11',title:'Closed-book anthology quotation retrieval',scope:'Anthology · exact words, paraphrase and source checking',summary:'Teaching lens: retrieve brief evidence from two assigned poems before reopening the text. Distinguish exact quotation from an honest paraphrase, identify speaker and context, and check accuracy after preserving the first attempt.',
cards:[['Separate feeling certain from being accurate','Attempt a brief reference without looking at the poem, then identify speaker and situation. Confidence is information about a feeling, not proof that every word is right. Where exact wording is uncertain, use an accurate paraphrase without quotation marks instead of inventing words that sound poetic.'],['Retrieve references that can serve a comparison','Choose two assigned poems and one shared focus, then explain how each remembered detail bears on it. A list of fragments does not yet show an argument. Keep differences in speaker, tense and context visible so that the comparison does not change a line’s meaning merely to create a neat match.'],['Verify after preserving the attempt','The independent workspace is memory practice, not an official anthology question. Suggested budget is 25 minutes, advisory rather than enforced. After submitting, reopen the assigned poems, correct attribution and wording, and save a separate revision. Later retrieval after an interval tests something different from rereading immediately.']],details:[['Exact quotation','Use quotation marks only for wording you can support.'],['Paraphrase','Signal your own accurate account without pretending it is the poet’s words.'],['Context','Check speaker and situation as well as remembered wording.']],people:[['Retrieving writer','Records the first memory-based attempt honestly.'],['Checking reader','Verifies against the assigned source after submission.'],['Revising writer','Corrects evidence while preserving the original attempt.']],movement:[['Retrieve','Attempt short references before looking.'],['Distinguish','Mark exact words and paraphrase honestly.'],['Verify','Check the assigned texts after first submission.'],['Return later','Test recall again after an interval.']],challenge:['What is the best choice when wording is uncertain?','Use an accurate paraphrase without quotation marks, then verify it after the attempt.','Invent a plausible phrase and present it as exact quotation.','Treat confidence alone as a source check.','Honest reference can support an argument without disguising uncertainty.','Keep your own wording distinct from exact textual words.'],practice:[['What must a quotation check include?','Wording, attribution and the relevant situation.','Only whether the phrase sounds impressive.','A guessed grade presented as official.','Accuracy includes who speaks and what the words mean in context.','accuracy'],['Why retrieve two poems around one focus?','It tests whether evidence can serve a comparative relation.','It proves every remembered fragment is relevant.','It removes the need to explain a difference.','Recall is useful when its application is examined too.','comparison'],['When should supported correction occur?','After the original unassisted response is preserved.','By silently replacing the first attempt before recording it.','Never, because confidence makes checking unnecessary.','Separate retrieval performance from assisted revision.','independence']],check:[['Which claim about confidence is accurate?','Confidence alone does not establish exact wording.','Feeling certain verifies a quotation automatically.','Attribution never affects accuracy.','A feeling and a checked reference are different kinds of evidence.','meaning'],['What is honest paraphrase?','Your own accurate account without pretending it is exact source wording.','Invented lines placed in quotation marks.','A changed speaker attributed to the poet.','Reference can be useful without false quotation.','accuracy'],['What is this independent task’s status?','Memory-based practice, not an official anthology examination question.','An automatic official mark from recalled fragments.','A compulsory timed paper with enforced conditions.','The task’s conditions and limits must be stated honestly.','assessment'],['Why return after a delay?','To test retrieval beyond immediate familiarity before checking again.','To guarantee forgetting is impossible after a save.','To avoid all further source verification.','Delayed recall needs a later opportunity for evidence.','recall']],writing:'Use the independent memory workspace for two assigned poems, then verify and revise the evidence after preserving the first response.',rubric:['Distinguish accurate quotation, honest paraphrase and uncertainty.','Attribute references correctly and explain their relevance to a shared focus.','Correct wording and reasoning after preserving the first unassisted attempt.'],extra:{independentWriting:true,independentTaskType:'retrieval',independentTaskLabel:'Memory-based anthology practice, not an official examination question.',independentIntro:'Work from memory before checking the assigned texts. Suggested budget: 25 minutes; timing is advisory, not enforced. Label paraphrases honestly.',independentPrompt:'Choose two Power and Conflict poems and a shared focus. From memory, give two brief references for each, identify their contexts, then develop a comparative paragraph. Do not invent quotations; label paraphrase. Verify sources only after submitting the first response.',independentExtractLabel:'Memory-based task · no supplied poem',independentExtract:''}}),
make({key:'workshop-12',title:'Timed anthology comparison assessment',scope:'Guided represented power · fresh London comparison',minutes:50,summary:'Teaching lens: a plan comparing the monument in Ozymandias with the portrait encounter in My Last Duchess can practise a shared question and significant difference. The independent task instead supplies London and lets you choose one other assigned poem.',
cards:[['Prepare a method rather than one fixed essay','Use Ozymandias and My Last Duchess to plan a shared question about represented authority. Identify a precise method in each and a difference in how control is exposed. This develops transferable reasoning; the independent task changes the supplied poem and focus, so a memorised pair argument cannot be pasted unchanged.'],['Choose the second poem for the actual task','In the independent comparison, read the supplied London text and choose another Power and Conflict poem whose methods address the effects of power. Defend the relation through a significant difference as well as a shared concern. Familiarity helps recall but does not itself establish relevance to this question.'],['Preserve the first comparison before support','Aim for about 45 minutes including planning and checking; timing is advisory, not enforced. This original practice provides the complete public-domain London text and keeps teaching guidance and criteria hidden until first submission. Your first response remains separate from revisions, and no automatic essay mark is awarded.']],details:[['Shared question','Frame a relation that both poems can help answer.'],['Significant difference','Explain different mechanisms rather than force identical meanings.'],['Task-led selection','Choose the partner because its methods serve the actual focus.']],people:[['Preparing writer','Practises comparison using a different guided pair.'],['Independent writer','Reads London and chooses a relevant second assigned poem.'],['Later reviewer','Examines a preserved comparative argument before revision.']],movement:[['Read','Attend to the fresh supplied poem and question.'],['Choose','Defend a second poem’s relevance.'],['Compare','Develop related claims through methods in both texts.'],['Check','Review reference accuracy and the logic of the relation.']],challenge:['Which plan best transfers to the fresh comparison?','Read London and select a second poem because its methods answer the actual focus.','Paste the complete guided-pair essay without reading the new task.','Choose a partner only because one long quotation is familiar.','A comparative method transfers through task-led selection and explanation.','Ask why each chosen detail serves the question now being asked.'],practice:[['What should the partner choice allow?','A supported shared focus and significant difference.','An identical situation and form by assumption.','Two unrelated essays with no reasoning between them.','Comparison develops through a relation that preserves differences.','selection'],['What is supplied in the independent task?','The complete public-domain London text, with the second poem chosen by the student.','A reproduced passage from every modern anthology poem.','An official examiner’s completed answer.','The task supplies one poem without pretending the whole anthology is reproduced.','conditions'],['What should checking improve?','The accuracy of references and the reasoning between both poems.','Only the number of lines copied into the answer.','A predicted mark invented by the app.','Editing should strengthen the actual comparative argument.','editing']],check:[['What determines the comparison route?','The fresh question and relevant methods in both selected texts.','A fixed essay applied to every task.','Only the title easiest to spell.','A route needs a reasoned relation to the task.','meaning'],['What should a significant difference do?','Develop the shared question through contrasting methods or responses.','Prove comparison is impossible.','Remove every shared concern from the answer.','Difference can sharpen the comparative judgment.','comparison'],['What happens to the first submitted argument?','It is preserved separately from later revisions.','It is replaced whenever a supported draft changes.','It automatically receives an official GCSE mark.','Preservation supports honest later review.','assessment'],['Which conclusion is analytical?','Explain what the compared methods show about the effects of power.','Repeat that both poems contain power and stop.','Rank the poems without evidence.','A judgment follows from the relation already analysed.','argument']],writing:'Practise a short comparison plan with the guided pair, then respond independently to the supplied London task and your chosen second poem.',rubric:['Sustain a comparison addressing the effects of power in London and a relevant second assigned poem.','Analyse precise methods and references in both texts, including a significant difference.','Maintain a coherent comparative judgment and accurate, qualified expression.'],sourceNote:'Guided views contain original commentary only. The independent task supplies the complete underlying public-domain London by William Blake, following AQA anthology spelling and lineation (typographic apostrophes normalised). Other assigned modern poems are not reproduced; use an authorised anthology. Original practice, not an official paper.',extra:{independentWriting:true,independentTaskType:'anthology-comparison',independentTaskLabel:'Original anthology comparison practice with one supplied poem and one student-selected poem.',independentIntro:'Read the supplied complete London and choose one other Power and Conflict poem. Aim for about 45 minutes including planning and checking. Timing is advisory, not enforced.',independentPrompt:'Compare how poets present the effects of power in London and one other poem from Power and Conflict. Analyse language, form and organisation, developing a relevant similarity and a significant difference.',independentExtractLabel:'Supplied poem · complete public-domain text',independentExtract:london}}),
make({key:'workshop-13',title:'Feedback-led anthology comparison redraft',scope:'Comparative writing · strengthen the relation and return later',summary:'Teaching lens: a comparison improves when its relation is explained more precisely, not merely when another isolated quotation is added. Preserve the first assessment, diagnose a real weakness and revise how evidence from both poems develops the focus.',
cards:[['Diagnose the comparative relation','Bring the first comparison assessment into this workshop if available. Use the criteria and any real teacher feedback to identify a specific problem: an irrelevant partner, two separate summaries, a forced match or an unsupported difference. No examiner’s mark or feedback is invented by the app; self-review should name the actual gap.'],['Make both poems work in the reasoning','If a paragraph presents one poem and then merely says similarly, explain the method-level relation instead. A significant difference may refine a claim about power more than an additional shared noun. Revise the connection and the use of evidence, not just the vocabulary used to announce comparison.'],['Keep the original and test evidence later','Save a separate version and explain what the change improves. The original first assessment is not overwritten. Later, retrieve the supporting reference from each poem before checking the anthology. Immediate completion does not prove long-term recall or the quality of an independent comparison; those require further evidence and review.']],details:[['Diagnosed relation','Identify what is missing between the two poem discussions.'],['Method-level connection','Explain how choices create a similarity or difference relevant to the focus.'],['Preserved first response','Use versions to inspect change without erasing the starting point.']],people:[['First comparison writer','Provides the original claim and evidence route.'],['Reviewer','Tests relevance and the logic between both texts.'],['Revising writer','Explains a substantive change and plans later retrieval.']],movement:[['Diagnose','Choose a specific weakness in the comparison.'],['Connect','Revise the relation through evidence in both texts.'],['Compare versions','Save and explain the reasoning change.'],['Return','Retrieve supporting evidence later, then verify it.']],challenge:['Which revision is substantive?','Explain how different methods develop the shared focus instead of only adding similarly.','Append an unrelated quotation without explaining a relation.','Invent a teacher’s mark to make the comparison appear finished.','Comparative reasoning improves when the relation becomes more precise.','Ask what the new wording explains about both poems together.'],practice:[['What should guide a redraft?','A specific gap in the actual comparison or real feedback.','A fabricated comment never received.','A rule that more quotations always mean better analysis.','Diagnosis requires evidence from the writing being revised.','diagnosis'],['Why can a significant difference help?','It can refine the shared claim rather than force identical meanings.','It proves no comparison can be made.','It removes the need to analyse both texts.','A relation becomes sharper when its limits are explained.','comparison'],['What remains separate from the redraft?','The original first assessment submission.','An official mark automatically supplied by the app.','No record at all of the initial reasoning.','A versioned record permits honest comparison.','versions']],check:[['What does the bring-in action do?','Copy the first assessment into an empty draft without changing its source.','Overwrite every assessment revision automatically.','Convert a knowledge score into an official comparison mark.','The source and the workshop have distinct records.','meaning'],['Which edit strengthens comparison?','Explain the relation between the methods used in both poems.','Insert similarly before two unrelated summaries.','Add a quotation because it is long rather than relevant.','A connective needs actual reasoning behind it.','argument'],['Which review claim is honest?','Use actual feedback or self-review against the criteria.','Every saved version has already been specialist graded.','The app guarantees an examiner’s approval.','Review needs real evidence rather than invented authority.','review'],['Why retrieve evidence later?','To test accurate recall beyond immediate familiarity before verifying the sources.','To prove saving makes future forgetting impossible.','To avoid ever reopening the anthology.','Durable learning requires a later opportunity to test retrieval.','recall']],writing:'Bring in your first anthology comparison if available. Diagnose one relational weakness, revise it through evidence in both texts and save a version with a brief explanation of the change.',rubric:['Diagnose a specific relevance or relational weakness using the actual writing.','Revise how methods and evidence in both texts develop the shared focus.','Compare versions honestly and plan later source-checked retrieval without claiming an automatic mark.'],extra:{revisionFrom:'lit.power-conflict.workshop-12'}}),
make({topic:'unseen',key:'workshop-01',title:'Unseen voice and speaker evidence workshop',scope:'A Birthday · speaker, imagery and an implied occasion',summary:'',
cards:[['Read a speaker before inventing a biography','Read the complete poem and summarise what the voice presents: joy associated with love’s arrival, expressed through a succession of comparisons and a call for celebration. The identity of the beloved is not explicitly confirmed as a biographical fact. A reading may explore possibilities, but the speaker is not automatically a complete personal diary of Rossetti.'],['Use vocabulary to clarify the image sequence','A water’d shoot is a watered young plant; halcyon suggests calm or peaceful conditions. A dais is a raised platform, vair a type of fur, and fleurs-de-lys stylised lily designs. The poem moves from natural comparisons towards commands for crafted decoration. Explain what that change lets the voice do instead of simply listing attractive objects.'],['Test the occasion through the whole poem','The birthday of my life can present a felt renewal rather than prove a literal calendar birthday. Repeated claims of joy and the later imperatives build an imagined celebration whose scale can exceed the ordinary. Support a reading through the change in stanza, syntax and imagery, and keep unconfirmed identities or dates qualified.']],details:[['My heart is like','Repeated similes build comparisons without making the heart literally a bird or tree.'],['Raise / Hang / Carve / Work','Imperatives move from describing joy towards imagining a constructed celebration. Dais: platform; vair: fur; fleurs-de-lys: stylised lilies.'],['birthday of my life','A metaphor can suggest renewal without confirming a literal date or the beloved’s identity.']],people:[['Poetic speaker','Expresses joy and commands an imagined celebration.'],['Implied love','Is significant to the voice without a fully confirmed personal identity.'],['Evidence-led reader','Distinguishes stated feeling, possible occasion and unverified biography.']],movement:[['Read','Give a plain account of the presented feeling.'],['Clarify','Use vocabulary glosses to follow the images.'],['Trace','Explain the turn from natural comparisons to decorative imperatives.'],['Qualify','Test a metaphorical occasion without inventing a biography.']],challenge:['Which reading stays closest to the evidence?','The voice presents love’s arrival as renewal, without confirming a literal birthday or a biographical identity.','The poem supplies a verified calendar date and names the beloved.','The heart literally becomes a bird and then a tree.','A metaphorical occasion can be interpreted without being converted into biography.','Distinguish what the voice states from an identity or date it does not confirm.'],practice:[['What changes between the two stanzas?','Natural comparisons give way to imperatives for an imagined crafted celebration.','The speaker stops expressing any feeling at all.','The poem becomes a verified building contract.','Syntax and image type shape a movement in the voice.','structure'],['How should the repeated similes be read?','They build analogies for feeling rather than literal transformations of an organ.','They establish that the speaker owns an actual rainbow shell.','They prove the poem is a scientific anatomy report.','A comparison presents a relation rather than physical identity.','methods'],['Which inference needs qualification?','The beloved’s precise identity or the occasion’s literal date.','The voice expresses gladness.','The second stanza contains commands.','The poem does not confirm every biographical possibility.','limits']],check:[['What can be stated securely about the speaker?','The voice expresses joy connected with love’s arrival.','It provides a complete verified biography of Rossetti.','It names the beloved and an exact calendar date.','Begin with explicit presentation before extending an inference.','meaning'],['What do the later imperatives contribute?','They imagine arranging a celebration rather than only comparing a feeling.','They prove the reader must literally commission a platform.','They cancel the significance of the earlier stanza.','The grammatical change develops the voice’s imaginative action.','methods'],['What does dais mean here?','A raised platform.','A type of angry weather.','A guaranteed literal birthday date.','Clarifying an unfamiliar word helps the image sequence make sense.','vocabulary'],['Which conclusion is qualified?','The metaphorical birthday can suggest renewal without confirming an exact biography.','Every first-person poem is a complete literal diary.','Any possible reading is equally supported without evidence.','Use the whole poem to support and limit the interpretation.','argument']],writing:'How does the voice in A Birthday present joy and renewal? Analyse the movement from similes to imperatives and qualify what the occasion and speaker can be known to be.',rubric:['Distinguish explicit feeling from an unconfirmed occasion or biography.','Analyse a precise image and the grammatical movement between the two stanzas.','Use the complete poem and clarified vocabulary to support a qualified interpretation.']})
];
